#!/usr/bin/env python3
"""Generate ``introspection_sdk/_sync/`` from ``introspection_sdk/_async/``.

Run ``uv run python scripts/gen_sync.py`` after editing ``_async/`` and
commit both trees. "Sync code generation" in AGENTS.md has the rules.
"""

from __future__ import annotations

import re
import shutil
import subprocess
import sys
from pathlib import Path

import unasync

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "introspection_sdk" / "_async"
TARGET = ROOT / "introspection_sdk" / "_sync"

HEADER = (
    "# Generated by scripts/gen_sync.py from {source}. Do not edit:\n"
    "# change the async source and run `uv run python scripts/gen_sync.py`.\n"
)

# Name tokens unasync renames, on top of its own defaults (__aenter__,
# __aexit__, __aiter__, __anext__, asynccontextmanager, AsyncIterable,
# AsyncIterator, AsyncGenerator, StopAsyncIteration) and the Async* /
# async_* / *_async rules in _Rule. A string literal is renamed only when
# its whole content is one of these names.
TOKENS = {
    # The source and generated packages.
    "_async": "_sync",
    # httpx / httpx2.
    "AsyncClient": "Client",
    "AsyncBaseTransport": "BaseTransport",
    "AsyncHTTPTransport": "HTTPTransport",
    "AsyncByteStream": "SyncByteStream",
    "aclose": "close",
    "aiter_bytes": "iter_bytes",
    "aiter_lines": "iter_lines",
    "aiter_raw": "iter_raw",
    "aread": "read",
    "handle_async_request": "handle_request",
}

# Regular expressions applied in order to each generated file, for what
# unasync cannot see as one token.
SUBSTITUTIONS: list[tuple[str, str]] = [
    # A block fenced by these comments exists only in the async twin.
    (
        r"^[ \t]*# unasync: async-only\b.*\n(?s:.*?)^[ \t]*# unasync: end\n\n?",
        "",
    ),
    (r"\bAwaitable\[((?:[^\[\]]|\[[^\[\]]*\])*)\]", r"\1"),
    # A cross-reference in prose, like :class:`AsyncPager`.
    (r"\bAsync([A-Z]\w*)", r"\1"),
    (r"\bAsynchronous\b", "Synchronous"),
    (r"\basynchronous\b", "synchronous"),
]


class _Rule(unasync.Rule):
    def _unasync_name(self, name: str) -> str:
        if name in self.token_replacements:
            return self.token_replacements[name]
        # AsyncTasks -> Tasks, _AsyncHttpClient -> _HttpClient.
        for prefix in ("Async", "_Async"):
            rest = name[len(prefix) :]
            if name.startswith(prefix) and rest[:1].isupper():
                return prefix[: -len("Async")] + rest
        # async_cursor_paginate -> cursor_paginate,
        # parse_ag_ui_events_async -> parse_ag_ui_events.
        if name.startswith("async_"):
            return name[len("async_") :]
        if name.endswith("_async"):
            return name[: -len("_async")]
        return name


def main() -> None:
    shutil.rmtree(TARGET, ignore_errors=True)
    sources = sorted(SOURCE.rglob("*.py"))
    unasync.unasync_files(
        [str(p) for p in sources], [_Rule("/_async/", "/_sync/", TOKENS)]
    )
    for src in sources:
        target = TARGET / src.relative_to(SOURCE)
        text = target.read_text()
        for pattern, replacement in SUBSTITUTIONS:
            text = re.sub(pattern, replacement, text, flags=re.MULTILINE)
        source = src.relative_to(ROOT).as_posix()
        target.write_text(HEADER.format(source=source) + text)
    # Sort the imports, drop the ones only the async code used, format.
    ruff = [sys.executable, "-m", "ruff"]
    for args in (["check", "--fix", "--select", "I,F401"], ["format"]):
        subprocess.run([*ruff, *args, "--quiet", TARGET], check=True)


if __name__ == "__main__":
    main()
